CREATE TABLE "riding_trainers" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "companyId" TEXT NOT NULL, "name" TEXT NOT NULL, "phone" TEXT, "email" TEXT, "specialties" TEXT, "bio" TEXT, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "riding_lesson_types" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "companyId" TEXT NOT NULL, "name" TEXT NOT NULL, "level" TEXT NOT NULL, "durationMinutes" INTEGER NOT NULL, "format" TEXT NOT NULL, "capacity" INTEGER NOT NULL DEFAULT 1, "price" DECIMAL(18,2) NOT NULL, "trainerId" TEXT, "description" TEXT, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "riding_lessons" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "companyId" TEXT NOT NULL, "lessonTypeId" TEXT NOT NULL, "trainerId" TEXT NOT NULL, "horseId" TEXT, "studentName" TEXT NOT NULL, "studentPhone" TEXT, "scheduledAt" TIMESTAMP(3) NOT NULL, "participants" INTEGER NOT NULL DEFAULT 1, "price" DECIMAL(18,2) NOT NULL, "status" TEXT NOT NULL DEFAULT 'scheduled', "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "equestrian_competitions" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "companyId" TEXT NOT NULL, "name" TEXT NOT NULL, "discipline" TEXT NOT NULL, "level" TEXT, "location" TEXT NOT NULL, "startDate" TIMESTAMP(3) NOT NULL, "endDate" TIMESTAMP(3), "registrationDeadline" TIMESTAMP(3), "entryFee" DECIMAL(18,2), "horseId" TEXT, "trainerId" TEXT, "riderName" TEXT, "status" TEXT NOT NULL DEFAULT 'planned', "result" TEXT, "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "horse_care_services" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "companyId" TEXT NOT NULL, "code" TEXT, "category" TEXT NOT NULL, "nameAr" TEXT NOT NULL, "nameEn" TEXT, "price" DECIMAL(18,2), "priceIncludesVat" BOOLEAN NOT NULL DEFAULT true, "unit" TEXT NOT NULL DEFAULT 'service', "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "riding_trainers_tenantId_companyId_idx" ON "riding_trainers"("tenantId","companyId");
CREATE INDEX "riding_lesson_types_tenantId_companyId_idx" ON "riding_lesson_types"("tenantId","companyId");
CREATE INDEX "riding_lessons_tenantId_companyId_scheduledAt_idx" ON "riding_lessons"("tenantId","companyId","scheduledAt");
CREATE INDEX "equestrian_competitions_tenantId_companyId_startDate_idx" ON "equestrian_competitions"("tenantId","companyId","startDate");
CREATE UNIQUE INDEX "horse_care_services_companyId_code_key" ON "horse_care_services"("companyId","code");
CREATE INDEX "horse_care_services_tenantId_companyId_category_idx" ON "horse_care_services"("tenantId","companyId","category");
